/* chip2/fx_cap.asm - at most DSP4_FX_REVERB_CAP engines on Reverb */
/* AUTO-GENERATED by tools/dsp/dsp_codegen.py - do not edit. */
/*
 * chip2/fx_cap.asm -- at most N engines on Type Reverb at once.
 *
 * PW's ruling, 2026-09-29: "cap reverbs to 3". S148 measured why -- six
 * engines from Type 0 (Echo) to Type 3 (Reverb) is +58,845 cycles/block,
 * and it is what puts chip 2 at 110.27 % in the in-use regime.
 *
 * THE DSP HALF OF A TWO-LAYER RULE. The host is the single writer and
 * publishes which selections are available so skins can grey them out;
 * this is the guard underneath, so that a write the host should not have
 * made cannot cost a missed block. It is the same two-layer shape as the
 * no-feedback rule S148 §4.3 designed for the aux matrix.
 *
 * HELD, NOT REFUSED, and that is a deliberate choice. `_fx_type_<nid>`
 * stays EXACTLY what the host wrote -- nothing on the wire is dropped or
 * rewritten, and a host read-back still says what was asked for --
 * while `_fx_type_live_<nid>` is what the engine reads. So:
 *
 *   * a fourth Reverb is never LOADED: the algorithm is not selected,
 *     no reverb state is set up, and the engine costs what its live type
 *     costs;
 *   * the moment one of the three moves off Reverb the held request is
 *     granted, with no further host traffic;
 *   * which three win is DETERMINISTIC -- an engine already RUNNING
 *     Reverb keeps its slot (a newcomer never evicts a reverb that is
 *     audibly running), and among the engines newly asking the lowest
 *     index wins -- and swapping takes one block, because every release
 *     is granted before any grant.
 *
 * THREE PASSES, all software loops over six engines at block rate, about
 * 180 instructions a block. It is under 0.05 % of chip 2 and it does not
 * touch the per-sample path at all.
 *
 * WHAT READS WHAT, so a bench tool is not left guessing: `_fx_type_` is
 * the REQUEST (the host's own word, unchanged), `_fx_type_live_` is what
 * RUNS. A capture that disagrees with the panel is the cap holding, and
 * the two words say so directly.
 */
#include "dsp_block.h"

#if DSP4_FX_REVERB_CAP > 0 && CHIP_ID == 2

#define FXCAP_N 6
#define FXCAP_REVERB 3

.section/dm seg_dmda;

.extern _fx_type_C2_FX_ENG_01;
.extern _fx_type_C2_FX_ENG_02;
.extern _fx_type_C2_FX_ENG_03;
.extern _fx_type_C2_FX_ENG_04;
.extern _fx_type_C2_FX_ENG_05;
.extern _fx_type_C2_FX_ENG_06;

/* THE LIVE TYPE, one per engine. Boots at 0 (Echo) whatever the
 * request is, and the guard grants on the first block -- which is
 * what makes the cap hold from block 1 even in a build whose
 * engines all DECLARE Reverb (DSP4_FX_TYPE_DECLARED=1). That arm
 * can no longer put six engines on Reverb, which is the point;
 * build the six-reverb capacity row with DSP4_FX_REVERB_CAP=0. */
.global _fx_type_live_C2_FX_ENG_01;
.var _fx_type_live_C2_FX_ENG_01 = 0;
.global _fx_type_live_C2_FX_ENG_02;
.var _fx_type_live_C2_FX_ENG_02 = 0;
.global _fx_type_live_C2_FX_ENG_03;
.var _fx_type_live_C2_FX_ENG_03 = 0;
.global _fx_type_live_C2_FX_ENG_04;
.var _fx_type_live_C2_FX_ENG_04 = 0;
.global _fx_type_live_C2_FX_ENG_05;
.var _fx_type_live_C2_FX_ENG_05 = 0;
.global _fx_type_live_C2_FX_ENG_06;
.var _fx_type_live_C2_FX_ENG_06 = 0;

/* The two sides, as address tables, so the passes are loops and not
 * six copies of the same six instructions. */
.var _fxcap_req[FXCAP_N] =
    _fx_type_C2_FX_ENG_01,
    _fx_type_C2_FX_ENG_02,
    _fx_type_C2_FX_ENG_03,
    _fx_type_C2_FX_ENG_04,
    _fx_type_C2_FX_ENG_05,
    _fx_type_C2_FX_ENG_06;
.var _fxcap_liv[FXCAP_N] =
    _fx_type_live_C2_FX_ENG_01,
    _fx_type_live_C2_FX_ENG_02,
    _fx_type_live_C2_FX_ENG_03,
    _fx_type_live_C2_FX_ENG_04,
    _fx_type_live_C2_FX_ENG_05,
    _fx_type_live_C2_FX_ENG_06;

.section/pm seg_pmco;

/*--------------------------------------------------------------
 * _fx_type_cap - run ONCE per block, before the first FX engine.
 * Clobbers r0-r3, r5-r7, r9, i0-i3, l0-l3.
 *-------------------------------------------------------------*/
.global _fx_type_cap;
_fx_type_cap:
    l0 = 0;
    l1 = 0;
    l2 = 0;
    l3 = 0;

    /* ---- 1: every NON-Reverb request is granted at once ----
     * Releases run before grants, which is what lets the host
     * move Reverb from engine 2 to engine 5 in a single block. */
    i0 = _fxcap_req;
    i1 = _fxcap_liv;
    r9 = FXCAP_N;
    r6 = FXCAP_REVERB;
.fxc_rel:
    r0 = dm(i0, 1);
    i2 = r0;
    r1 = dm(i2, 0);               /* what the host asked for   */
    r2 = dm(i1, 1);
    i3 = r2;
    comp(r1, r6);
    if eq jump (pc, .fxc_rel_next);
    dm(i3, 0) = r1;
.fxc_rel_next:
    r9 = r9 - 1;
    if ne jump (pc, .fxc_rel);

    /* ---- 2: how many are on Reverb now ---- */
    i1 = _fxcap_liv;
    r5 = 0;
    r9 = FXCAP_N;
.fxc_cnt:
    r2 = dm(i1, 1);
    i3 = r2;
    r3 = dm(i3, 0);
    comp(r3, r6);
    if ne jump (pc, .fxc_cnt_next);
    r5 = r5 + 1;
.fxc_cnt_next:
    r9 = r9 - 1;
    if ne jump (pc, .fxc_cnt);

    /* ---- 3: grant what fits ----
     * An engine already on Reverb is skipped, so it keeps its slot
     * however high its index: a newcomer never evicts a reverb that
     * is audibly running. Among the engines newly asking, the walk
     * is in index order, so the lowest win.
     * A request that does not fit is HELD: the live word is left
     * alone, the engine keeps running whatever it was running, and
     * the request is still there to be granted next block. */
    i0 = _fxcap_req;
    i1 = _fxcap_liv;
    r9 = FXCAP_N;
    r7 = DSP4_FX_REVERB_CAP;
.fxc_grant:
    r0 = dm(i0, 1);
    i2 = r0;
    r1 = dm(i2, 0);
    r2 = dm(i1, 1);
    i3 = r2;
    r3 = dm(i3, 0);
    comp(r1, r6);
    if ne jump (pc, .fxc_grant_next);   /* not asking for Reverb */
    comp(r3, r6);
    if eq jump (pc, .fxc_grant_next);   /* already on it         */
    comp(r5, r7);
    if ge jump (pc, .fxc_grant_next);   /* HELD: the cap is full */
    dm(i3, 0) = r6;
    r5 = r5 + 1;
.fxc_grant_next:
    r9 = r9 - 1;
    if ne jump (pc, .fxc_grant);
    rts;
_fx_type_cap.end:

#endif
